using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Hand of Vecna (2014 ruleset). Item of the 2014 Dungeon Master's Guide outside the SRD: name and texts written by RealmForge (Italian and English).
///	</summary>
public static class HandOfVecna2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("hand-of-vecna", null, 0, MagicItemType.WondrousItem, ItemRarity.Artifact, true, ContentSource.RealmForge,
			Charges(8, ItemRecharge.LongRest, "1d4+4", Ability(MagicEffectKind.SetAbilityScore, 20, AbilityScore.Strength)),
			("Mano di Vecna", "Oggetto meraviglioso, artefatto (richiede sintonia)",
			"Ciò che resta di Vecna, il più grande dei lich, dopo il tradimento del suo luogotenente Kas (vedi *Occhio di Vecna*): una mano sinistra mummificata e raggrinzita, che cerca ancora di compiere la volontà del Sussurrato.\n\nPer entrare in sintonia con la mano, il personaggio deve tagliarsi la mano sinistra all'altezza del polso e premere l'artefatto contro il moncherino: la mano vi si innesta e diventa un'appendice funzionante. Se viene rimossa, il personaggio muore.\n\n***Proprietà casuali.*** 1 proprietà benefica minore, 1 proprietà benefica maggiore e 1 proprietà dannosa minore.\n\n***Proprietà della mano.*** L'allineamento del personaggio diventa neutrale malvagio e ottiene i seguenti benefici:\n\n- Il suo punteggio di Forza diventa 20, a meno che non sia già 20 o superiore.\n- Ogni attacco con incantesimo in mischia effettuato con la mano, e ogni attacco con arma in mischia con un'arma che impugna, infligge 2d8 danni da freddo extra quando colpisce.\n- La mano ha 8 cariche. Con un'azione, il personaggio può consumarne una o più per lanciare uno degli incantesimi seguenti (CD 18): *dito della morte* (5 cariche), *lentezza* (2 cariche), *sonno* (1 carica) o *teletrasporto* (3 cariche). All'alba di ogni giorno la mano recupera 1d4 + 4 cariche consumate. Ogni volta che il personaggio lancia un incantesimo con la mano, questa lancia su di lui *suggestione* (CD 18), chiedendogli di compiere un atto malvagio, che il GM può decidere o lasciare a lui.\n\n***Occhio e Mano insieme.*** Se il personaggio è in sintonia sia con la mano sia con l'occhio, ottiene inoltre questi benefici:\n\n- È immune alle malattie e ai veleni.\n- Usare la vista a raggi X dell'occhio non gli causa mai indebolimento.\n- Ha premonizioni del pericolo e, a meno che non sia incapacitato, non può essere sorpreso.\n- Se inizia il suo turno con almeno 1 punto ferita, recupera 1d10 punti ferita.\n- Se una creatura ha uno scheletro, il personaggio può tentare di ridurne le ossa in gelatina con un tocco della mano: con un'azione effettua un attacco in mischia contro una creatura a portata, usando a scelta il suo bonus di attacco in mischia con le armi o con gli incantesimi. Se colpisce, il bersaglio deve superare un tiro salvezza su Costituzione con CD 18, altrimenti scende a 0 punti ferita.\n- Può usare un'azione per lanciare *desiderio*; non può riusare questa proprietà finché non sono passati 30 giorni.\n\n***Distruggere la mano.*** Se l'Occhio e la Mano di Vecna sono innestati sulla stessa creatura e questa viene uccisa dalla *Spada di Kas*, entrambi prendono fuoco, si riducono in cenere e sono distrutti per sempre. Qualsiasi altro tentativo sembra riuscire, ma l'artefatto ricompare in uno dei covi segreti di Vecna.", null),
			("Hand of Vecna", "Wondrous item, artifact (requires attunement)",
			"What remains of Vecna, the greatest of liches, after the betrayal of his lieutenant Kas (see *Eye of Vecna*): a mummified, shriveled left hand that still seeks to carry out the Whispered One's will.\n\nTo attune to the hand, you must cut off your left hand at the wrist and press the artifact against the stump: it grafts itself there and becomes a working appendage. If it is ever removed, you die.\n\n***Random Properties.*** 1 minor beneficial property, 1 major beneficial property and 1 minor detrimental property.\n\n***Properties of the Hand.*** Your alignment becomes neutral evil and you gain the following benefits:\n\n- Your Strength score becomes 20, unless it is already 20 or higher.\n- Any melee spell attack you make with the hand, and any melee weapon attack with a weapon it holds, deals an extra 2d8 cold damage on a hit.\n- The hand has 8 charges. As an action, you can expend one or more of them to cast one of these spells (DC 18): *finger of death* (5 charges), *sleep* (1 charge), *slow* (2 charges) or *teleport* (3 charges). The hand regains 1d4 + 4 expended charges daily at dawn. Each time you cast a spell from it, the hand casts *suggestion* on you (DC 18), demanding that you commit an evil act, which the DM may pick or leave to you.\n\n***Eye and Hand Together.*** If you are attuned to both the hand and the eye, you also gain these benefits:\n\n- You are immune to disease and poison.\n- Using the eye's X-ray vision never causes you exhaustion.\n- You have premonitions of danger and, unless incapacitated, can't be surprised.\n- If you start your turn with at least 1 hit point, you regain 1d10 hit points.\n- If a creature has a skeleton, you can try to turn its bones to jelly with a touch of the hand: as an action, make a melee attack against a creature within reach, using your choice of your melee weapon or spell attack bonus. On a hit, the target must succeed on a DC 18 Constitution saving throw or drop to 0 hit points.\n- You can use an action to cast *wish*; you can't use this property again until 30 days have passed.\n\n***Destroying the Hand.*** If the Eye and Hand of Vecna are grafted onto the same creature and that creature is slain by the *Sword of Kas*, both burst into flame, turn to ash and are destroyed forever. Any other attempt seems to work, but the artifact reappears in one of Vecna's hidden vaults.", null));
	}
}
